@implements IAsyncDisposable
@inject IJSRuntime JS

<div @ref="_element">
    @ChildContent
</div>

@code {
    [Parameter] public RenderFragment? ChildContent { get; set; }
    [Parameter] public int TimeoutSeconds { get; set; } = 300;
    [Parameter] public EventCallback OnIdle { get; set; }
    [Parameter] public EventCallback OnActive { get; set; }

    private ElementReference _element;
    private IJSObjectReference? _module;
    private DotNetObjectReference<UserActivityTracker>? _dotNetRef;
    private System.Timers.Timer? _timer;
    private bool _isIdle;
    private bool _disposed;

    protected override void OnInitialized()
    {
        _dotNetRef = DotNetObjectReference.Create(this);
        _timer = new System.Timers.Timer(TimeoutSeconds * 1000);
        _timer.AutoReset = false;
        _timer.Elapsed += OnTimerElapsed;
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            _module = await JS.InvokeAsync<IJSObjectReference>(
                "import", "./_content/sv-a03f456cdd9f4b52be95a430fb0dc9ad/Components/UserActivityTracker.razor.js");
            await _module.InvokeVoidAsync("init", _element, _dotNetRef);
            _timer?.Start();
        }
    }

    [JSInvokable]
    public async Task OnUserActivity()
    {
        if (_disposed) return;

        _timer?.Stop();
        _timer?.Start();

        if (_isIdle)
        {
            _isIdle = false;
            await InvokeAsync(OnActive.InvokeAsync);
        }
    }

    private async void OnTimerElapsed(object? sender, System.Timers.ElapsedEventArgs e)
    {
        if (_disposed) return;

        _isIdle = true;
        await InvokeAsync(OnIdle.InvokeAsync);
    }

    public async ValueTask DisposeAsync()
    {
        _disposed = true;

        if (_timer is not null)
        {
            _timer.Elapsed -= OnTimerElapsed;
            _timer.Stop();
            _timer.Dispose();
            _timer = null;
        }

        if (_module is not null)
        {
            try
            {
                await _module.InvokeVoidAsync("dispose");
                await _module.DisposeAsync();
            }
            catch (JSDisconnectedException) { }
            _module = null;
        }

        _dotNetRef?.Dispose();
        _dotNetRef = null;
    }
}

