let element = null;
let dotNetRef = null;
let throttleTimer = null;
const THROTTLE_MS = 250;

const events = ['mousemove', 'keydown', 'click', 'scroll', 'touchstart'];

function handleActivity() {
    if (throttleTimer) return;
    throttleTimer = setTimeout(() => { throttleTimer = null; }, THROTTLE_MS);
    dotNetRef?.invokeMethodAsync('OnUserActivity');
}

export function init(el, ref) {
    element = el;
    dotNetRef = ref;
    for (const event of events) {
        element.addEventListener(event, handleActivity, { passive: true });
    }
}

export function dispose() {
    if (element) {
        for (const event of events) {
            element.removeEventListener(event, handleActivity);
        }
    }
    if (throttleTimer) {
        clearTimeout(throttleTimer);
        throttleTimer = null;
    }
    element = null;
    dotNetRef = null;
}

